-- Generated by `supabase@3.0.0 migration new target_sticker_pack_seventeen`.
-- Preserve immutable purchases and income. Extend the private catalog from4to17.
SELECT pg_advisory_xact_lock(991101);
DO $guard$
BEGIN
  IF (SELECT md5(prosrc) FROM pg_proc WHERE oid='public.target_shop_rpc(text,text,jsonb)'::regprocedure)
      IS DISTINCT FROM '0a213b5f2acef0e67b8d372dfec7f367' OR
     (SELECT md5(prosrc) FROM pg_proc WHERE oid='target_private.wallet_snapshot(uuid)'::regprocedure)
      IS DISTINCT FROM 'fc4540561cbbf2ad4134f88fecc996c3' OR
     (SELECT md5(prosrc) FROM pg_proc WHERE oid='target_private.enforce_gacha_price_protocol()'::regprocedure)
      IS DISTINCT FROM '5ba5bb472b32ac684c86b44c2214a913' THEN
    RAISE EXCEPTION 'Target wallet changed; review the catalog migration again';
  END IF;
  IF EXISTS(SELECT 1 FROM target_private.profiles p WHERE p.spent_points IS DISTINCT FROM
      coalesce((SELECT sum(d.cost) FROM target_private.sticker_draws d WHERE d.member_id=p.member_id),0)) THEN
    RAISE EXCEPTION 'Target immutable spending and receipts do not agree';
  END IF;
END $guard$;

CREATE TABLE target_private.sticker_catalog (
  id text PRIMARY KEY CHECK(id ~ '^[a-z][a-z0-9-]{0,31}$'),
  ordinal smallint NOT NULL UNIQUE CHECK(ordinal BETWEEN 1 AND 17)
);
ALTER TABLE target_private.sticker_catalog ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE target_private.sticker_catalog FROM PUBLIC,anon,authenticated;
INSERT INTO target_private.sticker_catalog(id,ordinal) VALUES
